    zone = _find(request.match_info["name"], _c)
    if not zone:
        return err("Zone nicht gefunden.", 404)
    player = request.match_info["player"]
    al = zone.get("allowlist", [])
    zone["allowlist"] = [p for p in al if str(p).lower() != player.lower()]
    _zones_save(_c)
